window.AtlasAnalytics={mount({before,api,getCatalog,onReset}){
 const section=document.createElement('section');section.id='atlas-analytics';section.className='atlas-analytics';
 section.innerHTML=`<h2>Visitor analytics</h2><p class="analytics-help">Anonymous browser visits, not verified people. Admin sessions and recognised bots are excluded. Counts begin when tracking is enabled.</p><div class="analytics-toolbar"><label>Range<select id="analytics-range"><option value="today">Today</option><option value="7">Last 7 days</option><option value="30" selected>Last 30 days</option><option value="all">Since reset</option></select></label><label>Reporting period<select id="analytics-period"></select></label><button type="button" id="analytics-refresh">Refresh</button><button type="button" id="analytics-reset">Reset analytics</button></div><p id="analytics-status" role="status" aria-live="polite"></p><div id="analytics-report"></div><p class="analytics-help">Dates use UTC. A visit ends after 30 minutes without activity; separate tabs may count separately. Project interest counts a project once per visit when opened or expanded, not when the full list loads. Country is approximate and can reflect a VPN; unavailable locations and devices appear as Unknown. No names, raw IPs, search text or precise locations are stored. Visit details expire after 365 days; aggregate totals remain.</p><dialog class="transfer-confirm"><form method="dialog"><h3>Are you sure?</h3><p>Start a new analytics reporting period? Previous periods remain available. Project records and versions will not change.</p><div class="transfer-confirm-actions"><button value="cancel">Cancel</button><button value="reset">Reset analytics</button></div></form></dialog>`;
 before.before(section);const $=selector=>section.querySelector(selector);let data=null,busy=false,country='',device='';
 const el=(tag,text,cls)=>{const item=document.createElement(tag);if(text!==undefined)item.textContent=text;if(cls)item.className=cls;return item;};
 const countryName=value=>{try{return value==='Unknown'?value:new Intl.DisplayNames(['en'],{type:'region'}).of(value);}catch{return value;}};
 const projectName=id=>{const projects=getCatalog()?.programs||[],index=projects.findIndex(p=>p.id===id);return index<0?'Archived project ('+id+')':'Project '+String(index+1).padStart(2,'0')+' · '+projects[index].name;};
 function render(){const root=$('#analytics-report');root.replaceChildren();const rows=data.rows.filter(r=>(!country||r.country===country)&&(!device||r.device===device)),visits=rows.reduce((n,r)=>n+r.visits,0),views=rows.reduce((n,r)=>n+r.views,0),countries=new Set(rows.filter(r=>r.visits&&r.country!=='Unknown').map(r=>r.country)).size,mobile=rows.filter(r=>r.device==='Mobile').reduce((n,r)=>n+r.visits,0);
 const cards=el('div',undefined,'analytics-cards');for(const [label,value]of [['Visits',visits],['Project views',views],['Countries',countries],['Mobile share',visits?Math.round(mobile/visits*100)+'%':'—']]){const card=el('div');card.append(el('strong',value),el('span',label));cards.append(card);}root.append(cards);
 if(country||device){const clear=el('button','Clear filters · '+[country&&countryName(country),device].filter(Boolean).join(' / '));clear.type='button';clear.onclick=()=>{country=device='';render();};root.append(clear);}
 if(!rows.length){root.append(el('p','No visits recorded for this period yet.','analytics-empty'));return;}
 const chart=el('section',undefined,'analytics-chart');chart.append(el('h3','Daily visits'),el('p','Desktop/PC · Mobile · Tablet / Unknown. Last 90 active days shown.','analytics-help'));
 const daily=new Map();for(const r of rows){if(!r.visits)continue;if(!daily.has(r.day))daily.set(r.day,{total:0,desktop:0,mobile:0,other:0});const d=daily.get(r.day);d.total+=r.visits;d[r.device==='Desktop/PC'?'desktop':r.device==='Mobile'?'mobile':'other']+=r.visits;}
 const values=[...daily].slice(-90),max=Math.max(1,...values.map(([,v])=>v.total)),bars=el('div',undefined,'analytics-bars');for(const [day,v]of values){const col=el('div',undefined,'analytics-day');col.title=`${day}: ${v.total} visits; ${v.desktop} desktop, ${v.mobile} mobile, ${v.other} other`;col.setAttribute('aria-label',col.title);const stack=el('div',undefined,'analytics-stack');for(const key of ['desktop','mobile','other']){const bar=el('span',undefined,'analytics-bar-'+key);bar.style.height=(v[key]/max*100)+'px';stack.append(bar);}col.append(stack,el('small',day.slice(5)));bars.append(col);}chart.append(bars);root.append(chart);
 const grid=el('div',undefined,'analytics-grid');
 function breakdown(title,key,label){const panel=el('section');panel.append(el('h3',title));const totals=new Map();for(const r of rows)if(r.visits)totals.set(r[key],(totals.get(r[key])||0)+r.visits);for(const [value,count]of [...totals].sort((a,b)=>b[1]-a[1])){const button=el('button',`${label(value)} · ${count} (${Math.round(count/Math.max(visits,1)*100)}%)`,'analytics-breakdown');button.type='button';button.style.setProperty('--share',count/Math.max(visits,1)*100+'%');button.onclick=()=>{if(key==='country')country=country===value?'':value;else device=device===value?'':value;render();};panel.append(button);}grid.append(panel);}
 breakdown('Countries','country',countryName);breakdown('Devices','device',x=>x);root.append(grid);
 const popular=el('section');popular.append(el('h3','Popular projects'));const totals=new Map();for(const r of rows)if(r.project)totals.set(r.project,(totals.get(r.project)||0)+r.views);if(!totals.size)popular.append(el('p','No projects opened yet.'));for(const [id,count]of [...totals].sort((a,b)=>b[1]-a[1])){const row=el('div',undefined,'analytics-project');const link=el('a',projectName(id));link.href='/?project='+encodeURIComponent(id)+'#'+encodeURIComponent(id);row.append(link,el('span',`${count} views · ${Math.round(count/Math.max(views,1)*100)}% of project views`));popular.append(row);}root.append(popular);
 const recent=el('details');recent.append(el('summary','Recent anonymous visits · up to 20'));let count=0;for(const visit of data.recent.filter(v=>(!country||v.country===country)&&(!device||v.device===device))){const row=el('div',undefined,'analytics-project');row.append(el('strong',new Date(visit.at).toLocaleString()+' · '+countryName(visit.country)+' · '+visit.device),el('p',visit.projects.length?visit.projects.map(projectName).join('; '):'No project opened'));recent.append(row);count++;}if(!count)recent.append(el('p','No recent visit details in this view.'));root.append(recent);
 }
 async function refresh(){if(busy)return;busy=true;$('#analytics-status').textContent='Loading analytics…';try{const selected=$('#analytics-period').value;data=await api('/api/analytics?range='+$('#analytics-range').value+(selected?'&period='+encodeURIComponent(selected):''));const select=$('#analytics-period');select.replaceChildren();for(const period of data.periods)select.add(new Option((period.id===data.current?'Current · ':'Previous · ')+(period.at?new Date(period.at).toLocaleString():'Initial reporting period'),period.id));select.value=data.period;$('#analytics-reset').disabled=data.period!==data.current;render();$('#analytics-status').textContent='Updated '+new Date().toLocaleTimeString();}catch(error){$('#analytics-status').textContent=error.message;}finally{busy=false;}}
 $('#analytics-refresh').onclick=refresh;$('#analytics-range').onchange=refresh;$('#analytics-period').onchange=()=>{country=device='';refresh();};
 $('#analytics-reset').onclick=()=>{if(!busy&&data?.period===data?.current){const dialog=$('dialog');dialog.returnValue='cancel';dialog.showModal();dialog.querySelector('[value=cancel]').focus();}};
 $('dialog').addEventListener('close',async()=>{if($('dialog').returnValue!=='reset'||busy)return;busy=true;$('#analytics-reset').disabled=true;try{await api('/api/analytics/reset',{method:'POST',body:JSON.stringify({period:data.current})});$('#analytics-period').value='';country=device='';await onReset?.();}catch(error){$('#analytics-status').textContent=error.message;}finally{busy=false;await refresh();}});
 return {refresh};
}};
